from lib import *
S = SS('w90')
steps = [
    step("ClientHello 是客户端的第一个包,全程明文。本机 Python 的这次握手:第一条 TLS 记录是 Handshake 类型,记录层版本写着 0x0301(旧版本号,为了兼容老的中间设备),长度 1529 字节;里面的握手消息类型 1 = ClientHello,长度 1525 字节。ClientHello 里的版本字段是 0x0303(TLS 1.2,同样为兼容),真正的版本在 supported_versions 扩展里:[0x0304 (TLS 1.3), 0x0303 (TLS 1.2)]。session_id 长度 32(TLS 1.3 的兼容模式)。扩展共 12 个:server_name(example.com)、supported_groups(X25519MLKEM768、x25519、secp256r1、x448、secp384r1、secp521r1、ffdhe2048、ffdhe3072)、ALPN(h2、http/1.1)、signature_algorithms(26 种)、psk_key_exchange_modes、key_share 等。key_share 里客户端已经把公钥发出去了:X25519MLKEM768(1216 字节公钥)和 x25519(32 字节公钥)——前者是后量子的混合密钥交换,这也是 ClientHello 长达 1529 字节的原因(只有 x25519 的 ClientHello 大概 300 字节上下,这是我的估算,没有实测对照)。", t=tl(S(1)), mark=lidx(S(1), '第一条记录', 'key_share', 'supported_groups'), done=lidx(S(1), 'server_name', 'ALPN', 'supported_versions', '扩展(12 个)'), b=bars([['X25519MLKEM768 公钥', 1216, '1216 字节'], ['x25519 公钥', 32, '32 字节'], ['ClientHello 记录', 1529, '1529 字节']], 1529, mark=[0], done=[1, 2]), kv=KV([['ClientHello', '1529 字节记录'], ['key_share', 'X25519MLKEM768(1216)+ x25519(32)'], ['supported_versions', 'TLS 1.3 / 1.2'], ['SNI', 'example.com(明文)']], ['key_share'])),
    step("服务器的回应。ServerHello 记录 1210 字节(明文):选了密码套件 TLS_AES_256_GCM_SHA384;扩展只有 supported_versions(选定 0x0304 = TLS 1.3)和 key_share——选定的组是 X25519MLKEM768,服务器的公钥(密文份额)1120 字节。客户端用自己的私钥和这个份额算出共享密钥,双方由此得到加密密钥。之后服务器发的所有记录:1 个 ChangeCipherSpec(1 字节,只是为了兼容中间设备)、4 个外层标成 ApplicationData 的加密记录(3852、477、57、34 字节),合计 4420 字节——里面是 EncryptedExtensions、Certificate、CertificateVerify、Finished 等,从外面已经看不出类型了。客户端那边是 Handshake 1529 字节、ChangeCipherSpec 1 字节、ApplicationData 69 和 73 字节(加密的 Finished 和请求)。", t=tl(S(2)), mark=lidx(S(2), 'ServerHello 记录', 'key_share 选定的组'), done=lidx(S(2), 'supported_versions 选定', '服务器→客户端 的全部 TLS 记录', '客户端→服务器 的全部', '服务器的 ServerHello 之后'), b=bars([['ServerHello(明文)', 1210, '1210 字节'], ['服务器后续加密记录合计', 4420, '4420 字节']], 4420, mark=[0], done=[1]), kv=KV([['套件', 'TLS_AES_256_GCM_SHA384'], ['key_share 选定', 'X25519MLKEM768(服务器份额 1120 字节)'], ['之后', '全部加密(4 个记录,4420 字节)']], ['key_share 选定'])),
    step("时间线上的往返。ClientHello 分成两个 TCP 段(1388 + 146 字节)在 +0 ms 发出;+155.7 ms、+155.7 ms、+156.1 ms 服务器回来 3 个段(1440 + 1440 + 758 字节),这是 ServerHello 加上一部分加密记录——一个往返 156 ms。奇怪的是第 4 个 1440 字节的段直到 +349.2 ms 才到(多等了约 193 ms,很可能是丢包后重传,我没有逐包验证),客户端在 +351.5 ms 才能发出 Finished(80 字节),所以这一次 Python 量到的 TLS 握手是 352 ms。这是个离群的样本:同一个服务器上重复 4 次的 TLS 1.3 握手是 164、164、184、156 ms,中位 164 ms,即一个往返加一点本机计算。TLS 1.3 的客户端发出 Finished 之后就可以立刻发应用数据。", t=tl(S(3)), mark=lidx(S(3), '349.2', '351.5'), done=lidx(S(3), '相对时间', '155.7', '156.1', 'ClientHello(+0 ms)', 'Python 量到的 TLS 握手'), b=bars([['服务器第 1~3 个段', 156, '+156 ms'], ['第 4 个段(离群)', 349, '+349 ms'], ['典型握手(中位 4 次)', 164, '164 ms']], 349, mark=[1], done=[0, 2]), kv=KV([['正常', '1 个往返(约 156~164 ms)'], ['这次的离群样本', '第 4 个段晚到 193 ms,握手 352 ms'], ['原因', '很可能丢包重传,没有验证']], ['这次的离群样本'])),
    step("对比 TLS 1.2。把同一个客户端的最高版本限制成 TLS 1.2:握手耗时 [310, 322, 415, 328] ms,中位 325 ms,是 TLS 1.3 的中位 164 ms 的两倍——多一个往返。协商结果是 TLSv1.2、ECDHE-ECDSA-AES128-GCM-SHA256。服务器→客户端的握手记录是 ServerHello(76 字节)、Certificate(3677 字节)、ServerKeyExchange(115 字节)、ServerHelloDone(4 字节),之后才是 NewSessionTicket(202 字节)和 ChangeCipherSpec。区别:TLS 1.2 里 Certificate 是明文的,路径上的任何设备都能读到;而 TLS 1.3 把 Certificate 放进了加密记录(上一节的 3852 字节那个)。", t=tl(S(4)), mark=lidx(S(4), 'TLS 1.2 握手耗时', 'TLS 1.2 握手里服务器'), done=lidx(S(4), 'TLS 1.3 握手耗时', 'TLS 1.2 服务器发出的握手消息类型'), b=bars([['TLS 1.3 握手(中位)', 164, '164 ms'], ['TLS 1.2 握手(中位)', 325, '325 ms']], 325, mark=[1], done=[0]), kv=KV([['TLS 1.3', '1 个往返,中位 164 ms'], ['TLS 1.2', '2 个往返,中位 325 ms'], ['证书', '1.2 明文;1.3 加密']], ['证书'])),
]
A = mkartw('w90', 90, '网络协议,TLS,TLS 1.3,握手,ClientHello,key_share,X25519MLKEM768,真实验证,动画演示',
    '抓包手工解析 example.com 的 TLS 1.3 握手:ClientHello 1529 字节(含 1216 字节的 X25519MLKEM768 后量子混合公钥),ServerHello 选定该组和 TLS_AES_256_GCM_SHA384,之后 4420 字节全是加密记录;握手中位 164 ms(1 个往返),TLS 1.2 要 325 ms(2 个往返)。',
    'TLS 1.3 把握手压缩到了一个往返,证书也不再明文。但它的 ClientHello 里藏着什么、服务器怎么回应、后量子密钥交换为什么让第一个包变成 1529 字节?这篇抓包后手工解析 TLS 记录和握手消息的每个字段,并和 TLS 1.2 对比。',
    [('1529 字节', 'Python 的 ClientHello 记录大小,其中 key_share 有 X25519MLKEM768 的 1216 字节公钥'), ('164 vs 325 ms', 'TLS 1.3 与 TLS 1.2 握手耗时的中位数(example.com,各 4 次)'), ('4420 字节', 'ServerHello 之后服务器发的加密记录合计,包含证书')],
    [('ClientHello', '<p>明文,包含 SNI、密码套件、支持的组、ALPN 和已经算好的 key_share 公钥。</p>'),
     ('ServerHello', '<p>选定套件和密钥交换组(X25519MLKEM768),此后全部加密。</p>'),
     ('往返数', '<p>正常 1 个往返;这次抓包里有一个段晚到 193 ms,握手 352 ms 是离群样本。</p>'),
     ('对比 TLS 1.2', '<p>多一个往返,Certificate 明文可读。</p>')],
    steps,
    [ENV_W + '。对 example.com:443 的真实 TLS 握手,en0 抓包后手工解析记录与握手消息(没有用任何 TLS 解析库);ClientHello 内容取决于本机 Python 3.14 / OpenSSL 的默认设置;第三节抓的那一次握手有一个离群样本',
     '没有验证:密钥派生(HKDF、握手密钥与应用密钥)的计算;解密 Certificate 等加密记录(需要密钥日志,没有做);HelloRetryRequest;ECH(加密 ClientHello);PSK 恢复(下面有一篇讲会话恢复);其它 TLS 实现(Go、Rust、浏览器)的 ClientHello 差异;X25519MLKEM768 的计算开销'],
    'TLS 1.3 握手')
